def git_blob(data):
 return hashlib.sha1(b"blob "+str(len(data)).encode()+b"\0"+data).hexdigest()

assert set(REPLACEMENTS)==set(PREVIEW_CONTRACT["base_source_blobs"])==set(PREVIEW_CONTRACT["source_blobs"])
for path,pair in REPLACEMENTS.items():
 target=Path(path)
 raw=target.read_bytes()
 assert git_blob(raw)==PREVIEW_CONTRACT["base_source_blobs"][path],("baseline drift",path)
 original=raw.decode("utf-8")
 old,new=pair
 assert old and original.count(old)==1,("missing or repeated approved source region",path)
 candidate=original.replace(old,new,1).encode("utf-8")
 assert git_blob(candidate)==PREVIEW_CONTRACT["source_blobs"][path],("candidate source drift",path)
 target.write_bytes(candidate)
print("PASS approved Player/toolbar source-only polish: six exact source Git blobs, original release untouched",flush=True)
